// FFmpeg/ffprobe adapter (v3 plan §7.4): spawn with argv arrays (shell:false),
// parameter whitelist upstream in the validator, output paths generated by the
// engine, stderr tail kept for evidence, subprocess timeout armed.

import { spawnSync } from 'node:child_process'
import { existsSync, readdirSync } from 'node:fs'
import { homedir } from 'node:os'
import { join } from 'node:path'
import { MediaError } from '../errors.js'
import type { AssetProbe, Storyboard } from '../types.js'

export type MediaBinKind = 'ffmpeg' | 'ffprobe'

export function resolveMediaBin(kind: MediaBinKind, explicit?: string): string | undefined {
  const envKey = kind === 'ffmpeg' ? 'MEDIA_FFMPEG_BIN' : 'MEDIA_FFPROBE_BIN'
  const candidates: Array<string | undefined> = [
    explicit,
    process.env[envKey],
    join(homedir(), 'AppData', 'Local', 'Microsoft', 'WinGet', 'Links', `${kind}.exe`),
  ]
  // npm-installed static binaries (newest first): ffmpeg-static 6.1.1 at
  // ffmpeg-new, legacy @ffmpeg-installer 4.1 at ffmpeg-dl, then any sibling
  for (const toolsDir of [join(homedir(), 'tools', 'ffmpeg-new'), join(homedir(), 'tools', 'ffmpeg-dl'), join(homedir(), 'tools', 'media')]) {
    candidates.push(...scanForBin(toolsDir, kind))
  }
  candidates.push(kind) // PATH
  for (const candidate of candidates) {
    if (!candidate) continue
    const probe = spawnSync(candidate, ['-version'], { encoding: 'utf-8', shell: false, windowsHide: true })
    if (probe.status === 0) return candidate
  }
  return undefined
}

function scanForBin(dir: string, kind: MediaBinKind): string[] {
  try {
    return readdirSync(dir, { recursive: true })
      .map(rel => String(rel))
      .filter(rel => rel === `${kind}.exe` || rel.endsWith(`\\${kind}.exe`) || rel.endsWith(`/${kind}.exe`))
      .map(rel => join(dir, rel))
      // prefer x64 builds when an arch archiver ships both
      .sort((a, b) => Number(b.includes('x64')) - Number(a.includes('x64')))
  } catch {
    return []
  }
}

export function requireMediaBin(kind: MediaBinKind, explicit?: string): string {
  const resolved = resolveMediaBin(kind, explicit)
  if (!resolved) {
    throw new MediaError('MEDIA_BIN_MISSING', `${kind} not found; set ${kind === 'ffmpeg' ? 'MEDIA_FFMPEG_BIN' : 'MEDIA_FFPROBE_BIN'} or install FFmpeg`)
  }
  return resolved
}

export function mediaBinVersion(bin: string): string {
  const result = spawnSync(bin, ['-version'], { encoding: 'utf-8', shell: false, windowsHide: true })
  return (result.stdout ?? '').split('\n')[0]?.trim() ?? 'unknown'
}

interface SpawnResult {
  code: number | null
  ms: number
  stderrTail: string
}

function runProcess(bin: string, args: string[], options: { cwd?: string; timeoutMs?: number } = {}): SpawnResult {
  const started = Date.now()
  const result = spawnSync(bin, args, {
    encoding: 'utf-8',
    shell: false,
    windowsHide: true,
    cwd: options.cwd,
    timeout: options.timeoutMs ?? 600000,
  })
  return {
    code: result.status,
    ms: Date.now() - started,
    stderrTail: (result.stderr ?? '').split('\n').filter(Boolean).slice(-6).join('\n'),
  }
}

export function synthesizeAudio(options: { ffmpeg: string; durationSec: number; outPath: string }): SpawnResult {
  return runProcess(options.ffmpeg, [
    '-y',
    '-f', 'lavfi', '-i', `sine=frequency=440:duration=${options.durationSec}`,
    '-af', `afade=t=in:d=1,afade=t=out:st=${Math.max(0, options.durationSec - 1)}:d=1,volume=0.35`,
    '-ar', '48000', '-ac', '2',
    options.outPath,
  ], { timeoutMs: 120000 })
}

export interface EncodeOptions {
  ffmpeg: string
  framesDir: string
  fps: number
  audioPath?: string
  outputPath: string
  /** burned via libass when provided; engine writes the SRT next to the frames */
  subtitlePath?: string
  subtitleFont?: string
  storyboard: Storyboard
  workCwd: string
}

export function encodeVideo(options: EncodeOptions): SpawnResult {
  const output = options.storyboard.output ?? {}
  const videoFilters: string[] = []
  if (options.subtitlePath) {
    videoFilters.push(`subtitles=${options.subtitlePath}:force_style='FontName=${options.subtitleFont ?? 'Microsoft YaHei'}'`)
  }
  const args = [
    '-y',
    '-framerate', String(options.fps),
    '-i', join(options.framesDir, 'f%05d.png'),
  ]
  if (options.audioPath) args.push('-i', options.audioPath)
  if (videoFilters.length > 0) args.push('-vf', videoFilters.join(','))
  args.push(
    '-c:v', output.videoCodec ?? 'libx264',
    '-preset', output.preset ?? 'medium',
    '-crf', String(output.crf ?? 20),
    '-pix_fmt', output.pixelFormat ?? 'yuv420p',
  )
  if (options.audioPath) args.push('-c:a', output.audioCodec ?? 'aac', '-b:a', '160k')
  args.push('-shortest', options.outputPath)
  return runProcess(options.ffmpeg, args, { cwd: options.workCwd, timeoutMs: 600000 })
}

export function probeVideo(ffprobe: string, file: string): AssetProbe {
  const result = spawnSync(
    ffprobe,
    ['-v', 'error', '-print_format', 'json', '-show_format', '-show_streams', file],
    { encoding: 'utf-8', shell: false, windowsHide: true, timeout: 120000 },
  )
  if (result.status !== 0 || !result.stdout) {
    throw new MediaError('MEDIA_PROBE_FAILED', `ffprobe could not parse ${file}`)
  }
  const parsed = JSON.parse(result.stdout) as {
    format?: { duration?: string }
    streams?: Array<{ codec_type?: string; codec_name?: string; width?: number; height?: number }>
  }
  const video = parsed.streams?.find(stream => stream.codec_type === 'video')
  const audio = parsed.streams?.find(stream => stream.codec_type === 'audio')
  return {
    durationSec: parsed.format?.duration ? Number(parsed.format.duration) : undefined,
    videoCodec: video?.codec_name,
    audioCodec: audio?.codec_name,
    width: video?.width,
    height: video?.height,
  }
}

export function hasSubtitleFilter(ffmpeg: string): boolean {
  const result = spawnSync(ffmpeg, ['-hide_banner', '-filters'], { encoding: 'utf-8', shell: false, windowsHide: true, timeout: 60000 })
  return (result.stdout ?? '').includes(' subtitles ')
}

export function extractStill(options: { ffmpeg: string; input: string; atSec: number; outPath: string }): SpawnResult {
  return runProcess(options.ffmpeg, ['-y', '-ss', String(options.atSec), '-i', options.input, '-frames:v', '1', options.outPath], { timeoutMs: 120000 })
}

export function outputExists(path: string): boolean {
  return existsSync(path)
}
